// @FIGURE_CODE_BEGIN
(function () {
  var W = 980, H = 560;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);
  var svgNode = draw.node;
  var root = draw.group();

  var ORANGE = '#F5901E', RED = '#F01111', BLK = '#000';
  var k = 48, OX = 85, OY = 430;          // world -> view
  var HALF = 0.8;                          // half side of square (world units)

  var state = { t: { x: 3.2, y: 3.0 }, s: { x: 3.2, y: -1.7 }, stage: 0, swap: false };
  var STAGE = { 'origin only': 0, 'apply t': 1, 'apply s': 2, 'show t+s': 3 };

  var LOX = -0.9, HIX = 10.3, LOY = -1.4, HIY = 6.4;

  function V(u, v) { return [OX + k * u, OY - k * v]; }
  function f1(v) { return (Math.round(v * 10) / 10).toFixed(1); }
  function clampN(v, a, b) { return v < a ? a : (v > b ? b : v); }

  /* ---------- small drawing helpers ---------- */
  function txt(g, str, x, y, o) {
    o = o || {};
    var t = g.plain(str);
    t.font({
      family: o.family || 'Georgia, "Times New Roman", serif',
      size: o.size || 16,
      weight: o.weight || 'normal',
      style: o.style || 'normal'
    });
    t.attr({
      x: x, y: y,
      'text-anchor': o.anchor || 'middle',
      'dominant-baseline': 'middle',
      fill: o.fill || '#000'
    });
    if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.halo, 'stroke-linejoin': 'round' });
    if (o.opacity != null) t.opacity(o.opacity);
    return t;
  }

  function arrow(g, p1, p2, color, width, op) {
