  /* ---------- matrix panel ---------- */
  function matrixBlock(g, x, y, label, rows, op, tip, title, body) {
    var bg = g.group();
    var cellW = 54, rowH = 26;
    txt(bg, label, x, y, { size: 16, anchor: 'start', weight: 'bold' });
    var mx = x + 16, my = y + 14;
    var contentX = mx + 10, rx = contentX + 3 * cellW + 10;
    var hgt = 3 * rowH;
    bg.polyline([[mx + 9, my], [mx, my], [mx, my + hgt], [mx + 9, my + hgt]])
      .fill('none').stroke({ color: '#333', width: 2 });
    bg.polyline([[rx - 9, my], [rx, my], [rx, my + hgt], [rx - 9, my + hgt]])
      .fill('none').stroke({ color: '#333', width: 2 });
