      for (var c = 0; c < 3; c++) {
        var isRed = (c === 2 && r < 2);
        txt(bg, rows[r][c], contentX + c * cellW + cellW / 2, my + r * rowH + rowH / 2, {
          family: 'ui-monospace, Consolas, monospace', size: 15,
          fill: isRed ? RED : '#111', weight: isRed ? 'bold' : 'normal'
