  /* ---------- main render ---------- */
  var handles = [];

  function render() {
    root.clear();
    handles = [];

    var t = state.t, s = state.s;
    var first = state.swap ? s : t, second = state.swap ? t : s;
    var fName = state.swap ? 's' : 't', sName = state.swap ? 't' : 's';
