    ax.line(OX, 476, OX, 52).stroke({ color: BLK, width: 3 });
    ax.polygon([[OX, 34], [OX - 9, 54], [OX + 9, 54]]).fill(BLK);
    txt(root, 'x', 626, 466, { size: 30, style: 'italic', halo: 3 });
    txt(root, 'y', 56, 40, { size: 30, style: 'italic', halo: 3 });

