    if (opA2 > 0.1) txt(root, sName, a2.mid[0], a2.mid[1], { size: 27, weight: 'bold', halo: 4, opacity: opA2 });
    if (aS) txt(root, 't+s', aS.mid[0], aS.mid[1], { size: 27, weight: 'bold', halo: 4, opacity: opSum });

