    /* ---- side panel ---- */
    root.line(668, 20, 668, 540).stroke({ color: '#dcdcdc', width: 1.5 });
    var PX = 686;
    txt(root, 't    = (' + f1(t.x) + ', ' + f1(t.y) + ')', PX, 36,
      { family: 'ui-monospace, Consolas, monospace', size: 15, anchor: 'start', fill: RED, weight: 'bold' });
    txt(root, 's    = (' + f1(s.x) + ', ' + f1(s.y) + ')', PX, 60,
      { family: 'ui-monospace, Consolas, monospace', size: 15, anchor: 'start', fill: RED, weight: 'bold' });
    txt(root, 't+s  = (' + f1(sum.x) + ', ' + f1(sum.y) + ')', PX, 84,
      { family: 'ui-monospace, Consolas, monospace', size: 15, anchor: 'start', fill: RED, weight: 'bold', opacity: st >= 3 ? 1 : 0.35 });

