  document.addEventListener('mouseup', function () { dragging = null; });

  /* ---------- controls ---------- */
  function setRange(id, v) {
    var el = document.getElementById(id + 'Input');
    var out = document.getElementById(id + 'Val');
    if (el) el.value = v;
    if (out) out.value = f1(v);
  }
  function syncInputs() {
    setRange('tx', state.t.x); setRange('ty', state.t.y);
    setRange('sx', state.s.x); setRange('sy', state.s.y);
  }

  window.update_tx = function (v) { state.t.x = v; render(); };
  window.update_ty = function (v) { state.t.y = v; render(); };
  window.update_sx = function (v) { state.s.x = v; render(); };
  window.update_sy = function (v) { state.s.y = v; render(); };
  window.update_stepPhase = function (val) { state.stage = STAGE[val] != null ? STAGE[val] : 0; render(); };
  window.toggle_swapOrder = function (on) { state.swap = !!on; render(); };
  window.trigger_reset = function () {
    state.t = { x: 3.2, y: 3.0 }; state.s = { x: 3.2, y: -1.7 };
    syncInputs(); render();
  };

  /* ---------- demo step player ---------- */
  var steps = [
    { title: 'The untranslated square',
      narration: 'An orange square sits centred on the origin of the xy-plane. Nothing has moved yet; this is the reference position (the faint shapes ahead show where the translations will lead).',
      state: { stepPhase: 'origin only', swapOrder: false } },
    { title: 'One translation t',
      narration: 'A red arrow t carries the square up and to the right. Drag the arrow tip: every point of the square moves by the same vector, and the matrix T(t) changes only in its third column, (tx, ty).',
      state: { stepPhase: 'apply t', swapOrder: false } },
    { title: 'A second translation s',
      narration: 'From the intermediate square, a second red arrow s displaces it again to the lower right. Two separate moves, two separate matrices.',
      state: { stepPhase: 'apply s', swapOrder: false } },
    { title: 'The composed vector t+s',
      narration: 'A single arrow from the origin straight to the final square closes the triangle: t+s. The product T(s)·T(t) has third column (tx+sx, ty+sy) — composition is just vector addition.',
      state: { stepPhase: 'show t+s', swapOrder: false } },
    { title: "Order doesn't matter",
      narration: 'Swap the order to s then t: the intermediate square moves elsewhere, but the final square and the arrow t+s are unchanged. Translation matrices commute.',
      state: { stepPhase: 'show t+s', swapOrder: true } }
  ];
  var cur = 0;

  function applyStep(i) {
    cur = (i + steps.length) % steps.length;
    var st = steps[cur];
    var sel = document.getElementById('stepPhaseInput');
    if (sel) sel.value = st.state.stepPhase;
    var cb = document.getElementById('swapOrderInput');
    if (cb) cb.checked = st.state.swapOrder;
    state.stage = STAGE[st.state.stepPhase];
    state.swap = st.state.swapOrder;
    document.getElementById('stepTitle').textContent = st.title;
    document.getElementById('demoNarration').textContent = st.narration;
    document.getElementById('stepLabel').textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;
    render();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  syncInputs();
  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A 2D translation displaces every point of a shape by the same vector, and composing two translations is just adding their vectors (a single translation t+s).
KEY INSIGHT (what students should walk away understanding): Chaining translations is nothing more than adding their vectors — two displacements always collapse into one.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
