    var Rg = root.group();
    square(Rg, OX2, 0, 0, 'Square at the origin (0, 0)', 'Start of the chain', 'Both translations are applied one after the other, starting from this square at the origin.');
    square(Rg, OX2, first.x, first.y, 'After ' + fN + ': centre (' + f1(first.x) + ', ' + f1(first.y) + ')', 'After the first translation', sqBody);
    if (st >= 2) {
      square(Rg, OX2, sum.x, sum.y, 'After both: centre (' + f1(sum.x) + ', ' + f1(sum.y) + ')', 'After both translations', 'The final centre is t + s = (' + f1(sum.x) + ', ' + f1(sum.y) + '). Two displacements always collapse into one.');
    }
    axes(Rg, OX2, RIGHTLEN);

    var a1 = arrow(Rg, P(OX2, 0, 0), P(OX2, first.x, first.y), RED, 5.5);
    hover(a1, fN + ' = (' + f1(first.x) + ', ' + f1(first.y) + ')', 'Translation ' + fN, 'The first displacement, ' + fN + ' = (' + f1(first.x) + ', ' + f1(first.y) + '). In homogeneous coordinates these two numbers are the third column of T(' + fN + ').');
    vlabel(Rg, a1, fN);

    if (st >= 2) {
      var a2 = arrow(Rg, P(OX2, first.x, first.y), P(OX2, sum.x, sum.y), RED, 5.5);
      hover(a2, sN + ' = (' + f1(second.x) + ', ' + f1(second.y) + ')', 'Translation ' + sN, 'The second displacement starts where the first ended. Its components (' + f1(second.x) + ', ' + f1(second.y) + ') are added on top of the first ones.');
      vlabel(Rg, a2, sN);
    }
    if (st >= 3) {
      var aS = arrow(Rg, P(OX2, 0, 0), P(OX2, sum.x, sum.y), RED, 5.5);
      hover(aS, 't+s = (' + f1(sum.x) + ', ' + f1(sum.y) + ')', 'The composed vector t + s', 'One arrow from the origin to the final square closes the triangle. Its components are (tx+sx, ty+sy): composing translations is exactly vector addition, and the order makes no difference.');
      vlabel(Rg, aS, 't+s');
    }

    handle(Rg, P(OX2, first.x, first.y), 'first', 'Drag to change ' + fN);
    if (st >= 2) handle(Rg, P(OX2, sum.x, sum.y), 'second', 'Drag to change ' + sN);
  }

  /* ---------- dragging ---------- */
  function clientToWorld(evt, ox) {
    var pt = svgNode.createSVGPoint();
    pt.x = evt.clientX; pt.y = evt.clientY;
    var m = svgNode.getScreenCTM();
    if (!m) return null;
    var p = pt.matrixTransform(m.inverse());
    return { x: (p.x - ox) / k, y: (OY - p.y) / k };
  }

  document.addEventListener('mousemove', function (e) {
    if (!dragging) return;
    var first = state.swap ? state.s : state.t;
    var second = state.swap ? state.t : state.s;
    if (dragging === 'leftT') {
      var wl = clientToWorld(e, OX1); if (!wl) return;
      state.t.x = clampN(wl.x, XMIN, XMAX);
      state.t.y = clampN(wl.y, YMIN, YMAX);
    } else {
      var w = clientToWorld(e, OX2); if (!w) return;
      var wx = clampN(w.x, XMIN, XMAX), wy = clampN(w.y, YMIN, YMAX);
      if (dragging === 'first') { first.x = wx; first.y = wy; }
      else { second.x = wx - first.x; second.y = wy - first.y; }
    }
    syncInputs(); render(); refreshPopup();
  });
  document.addEventListener('mouseup', function () { dragging = null; });

  /* ---------- matrices popup ---------- */
  function pad(s, n) { s = String(s); while (s.length < n) s = ' ' + s; return s; }
  function mrow(a, b, c) { return '| ' + pad(a, 4) + '  ' + pad(b, 4) + '  ' + pad(c, 5) + ' |'; }
  function mat(v) { return [mrow(1, 0, f1(v.x)), mrow(0, 1, f1(v.y)), mrow(0, 0, 1)]; }

  function refreshPopup() {
    if (!state.matrices) return;
    var t = state.t, s = state.s, sum = { x: t.x + s.x, y: t.y + s.y };
    var A = mat(t), B = mat(s), C = mat(sum);
    var body =
      'A point (x, y) is written (x, y, 1), so a translation becomes a 3x3 matrix whose THIRD COLUMN holds the displacement.\n\n' +
      'T(t) =        T(s) =        T(s)·T(t) =\n' +
      A[0] + '   ' + B[0] + '   ' + C[0] + '\n' +
      A[1] + '   ' + B[1] + '   ' + C[1] + '\n' +
      A[2] + '   ' + B[2] + '   ' + C[2] + '\n\n' +
      'Multiplying leaves the 2x2 block as the identity and simply ADDS the two third columns: (' +
      f1(t.x) + ', ' + f1(t.y) + ') + (' + f1(s.x) + ', ' + f1(s.y) + ') = (' + f1(sum.x) + ', ' + f1(sum.y) + ').\n' +
      'Because addition commutes, T(s)·T(t) = T(t)·T(s): the order of two translations never matters.';
    showPopup('Homogeneous matrices of the two translations', body);
  }

  /* ---------- controls ---------- */
  function setRange(id, v) {
    var el = document.getElementById(id + 'Input'), out = document.getElementById(id + 'Val');
    if (el) el.value = v;
    if (out) out.value = f1(v);
  }
  function syncInputs() {
    setRange('tx', state.t.x); setRange('ty', state.t.y);
    setRange('sx', state.s.x); setRange('sy', state.s.y);
    document.getElementById('roT').textContent = 't   = (' + f1(state.t.x) + ', ' + f1(state.t.y) + ')';
    document.getElementById('roS').textContent = 's   = (' + f1(state.s.x) + ', ' + f1(state.s.y) + ')';
    document.getElementById('roSum').textContent = 't+s = (' + f1(state.t.x + state.s.x) + ', ' + f1(state.t.y + state.s.y) + ')';
  }

  window.update_tx = function (v) { state.t.x = v; syncInputs(); render(); refreshPopup(); };
  window.update_ty = function (v) { state.t.y = v; syncInputs(); render(); refreshPopup(); };
  window.update_sx = function (v) { state.s.x = v; syncInputs(); render(); refreshPopup(); };
  window.update_sy = function (v) { state.s.y = v; syncInputs(); render(); refreshPopup(); };
  window.update_stepPhase = function (val) { state.stage = (STAGE[val] != null) ? STAGE[val] : 3; render(); };
  window.toggle_swapOrder = function (on) { state.swap = !!on; render(); refreshPopup(); };
  window.toggle_showMatrices = function (on) {
    state.matrices = !!on;
    if (state.matrices) refreshPopup(); else hidePopup();
  };
  window.trigger_reset = function () {
    state.t = { x: 3.2, y: 3.0 }; state.s = { x: 3.2, y: -1.7 };
    syncInputs(); render(); refreshPopup();
  };

  /* ---------- demo step player ---------- */
  var steps = [
    {
      title: 'The figure as printed',
      narration: 'Left: an orange square at the origin, a red arrow t, and the same square displaced by t. Right: the same start, then a second displacement s, and the single arrow t+s that reaches the very same final square.',
      state: { stepPhase: 'show t+s', swapOrder: false, showMatrices: false }
    },
    {
      title: 'First translation t',
      narration: 'Build the right panel up in stages. Only t is applied so far — exactly the left panel. Drag the red dot at the arrow tip: every corner of the square moves by the identical vector.',
      state: { stepPhase: 'apply t', swapOrder: false, showMatrices: false }
    },
    {
      title: 'Second translation s',
      narration: 'A second red arrow s starts at the intermediate square and displaces it again, down and to the right. Two moves, two vectors, two new squares.',
      state: { stepPhase: 'apply s', swapOrder: false, showMatrices: false }
    },
    {
      title: 'The composed vector t+s',
      narration: 'One arrow from the origin to the final square closes the triangle: t+s = (tx+sx, ty+sy). The pair of translations is indistinguishable from this single translation.',
      state: { stepPhase: 'show t+s', swapOrder: false, showMatrices: false }
    },
    {
      title: "Order doesn't matter",
      narration: 'Swap to s then t: the intermediate square lands elsewhere, but the final square and the arrow t+s are unchanged. The matrix popup shows the same sum in the third column of the product.',
      state: { stepPhase: 'show t+s', swapOrder: true, showMatrices: true }
    }
  ];
  var cur = 0;

  function applyStep(i) {
    cur = (i + steps.length) % steps.length;
    var st = steps[cur];
    var sel = document.getElementById('stepPhaseInput'); if (sel) sel.value = st.state.stepPhase;
    var cb = document.getElementById('swapOrderInput'); if (cb) cb.checked = st.state.swapOrder;
    var mb = document.getElementById('showMatricesInput'); if (mb) mb.checked = st.state.showMatrices;
    state.stage = STAGE[st.state.stepPhase];
    state.swap = st.state.swapOrder;
    state.matrices = st.state.showMatrices;
    document.getElementById('stepTitle').textContent = st.title;
    document.getElementById('demoNarration').textContent = st.narration;
    document.getElementById('stepLabel').textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;
    render();
    if (state.matrices) refreshPopup(); else hidePopup();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  syncInputs();
  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A 2D translation displaces every point of a shape by the same vector, and composing two translations is just adding their vectors (a single translation t+s).
KEY INSIGHT (what students should walk away understanding): Chaining translations is nothing more than adding their vectors — two displacements always collapse into one.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "A 2D translation displaces every point of a shape by the same vector, and composing two translations is just adding their vectors (a single translation t+s).",
  "figureType": "diagram",
  "elements": [
