    }
  ],
  "demo_steps": [
    {
      "title": "The figure as printed",
      "narration": "Left panel: an orange square at the origin, a red arrow t, and the same square displaced by t — both drawn fully opaque, exactly as in the book. The right panel so far shows only that same single translation.",
